154	    public Settings find(String sheetId) {
155	        Map<String, NavigableMap<LocalDate, String>> dated = new HashMap<>();
156	        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_value WHERE sheet_id = ?",
157	                (RowCallbackHandler) (rs) -> dated.computeIfAbsent(rs.getString("setting_key"), (k) -> new TreeMap<>())
158	                        .put(rs.getDate("from_date").toLocalDate(), rs.getString("setting_value")), sheetId);
159	        Map<String, String> perms = new HashMap<>();
160	        jdbc.query("SELECT action, roles FROM setting_perm WHERE sheet_id = ?",
161	                (RowCallbackHandler) (rs) -> perms.put(rs.getString("action"), rs.getString("roles")), sheetId);
162	        List<Settings> found = jdbc.query("SELECT today, policy_date, period_numbering_from, grace_days, entry_date, pot, fiscal_start_month, alert_threshold, escalate_after, review_sla, proof_kinds, default_grade, score_mid, score_high, score_log FROM sheet WHERE id = ?",
163	                (rs, n) -> new Settings(sheetId, rs.getDate("today").toLocalDate(), dated,
164	                        rs.getDate("policy_date") == null ? null : rs.getDate("policy_date").toLocalDate(),
165	                        rs.getDate("period_numbering_from") == null ? null : rs.getDate("period_numbering_from").toLocalDate(), perms,
166	                        rs.getObject("grace_days", Integer.class),
167	                        rs.getDate("entry_date") == null ? null : rs.getDate("entry_date").toLocalDate(),
168	                        rs.getBigDecimal("pot"), rs.getObject("fiscal_start_month", Integer.class),
169	                        rs.getBigDecimal("alert_threshold"), rs.getObject("escalate_after", Integer.class),
170	                        rs.getObject("review_sla", Integer.class), rs.getString("proof_kinds"), rs.getString("default_grade"),
171	                        rs.getObject("score_mid", Integer.class), rs.getObject("score_high", Integer.class), rs.getBoolean("score_log")),
172	                sheetId);
173	        return found.isEmpty() ? new Settings(sheetId, null, dated, null, null, perms, null, null, null, null, null, null, null, null, null, null, null, false) : found.get(0);
174	    }
175	
176	    /** Records a dated setting's value from a date, replacing any value already recorded from it. */
177	    public void record(String sheetId, String key, LocalDate from, String value) {
178	        jdbc.update("MERGE INTO setting_value (sheet_id, setting_key, from_date, setting_value) KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)",
179	                sheetId, key, java.sql.Date.valueOf(from), value);
180	        history(sheetId, key, from, value);
181	    }
182	
183	    /** Keeps a setting's value in its history, with the sheet's today now. */
184	    private void history(String sheetId, String key, LocalDate from, String value) {
185	        jdbc.update("INSERT INTO setting_history (sheet_id, setting_key, from_date, setting_value, set_on)"
186	                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
187	                sheetId, key, from == null ? null : java.sql.Date.valueOf(from), value, sheetId);
188	    }
189	
190	    /**
191	     * The sheet's settings as they stood at the end of {@code day}: each dated value, the policy date
192	     * and the pot as last recorded while the sheet's today was on or before it, and that date standing in for
193	     * the sheet's today. The others are as they are now.
194	     */
195	    public Settings findAsOf(String sheetId, LocalDate day) {
196	        Settings now = find(sheetId);
197	        Map<String, NavigableMap<LocalDate, String>> dated = new HashMap<>();
198	        LocalDate[] policy = { null };
199	        boolean[] policyKept = { false };
200	        BigDecimal[] pot = { null };
201	        boolean[] potKept = { false };
202	        jdbc.query("SELECT setting_key, from_date, setting_value, set_on FROM setting_history WHERE sheet_id = ? ORDER BY id",
203	                (RowCallbackHandler) (rs) -> {
204	                    String key = rs.getString("setting_key");
205	                    String value = rs.getString("setting_value");
206	                    boolean counts = !rs.getDate("set_on").toLocalDate().isAfter(day);
207	                    if (POLICY_DATE.equals(key)) {
208	                        policyKept[0] = true;
209	                        if (counts) policy[0] = value.isBlank() ? null : LocalDate.parse(value);
210	                    } else if (POT.equals(key)) {
211	                        potKept[0] = true;
212	                        if (counts) pot[0] = value.isBlank() ? null : new BigDecimal(value);
213	                    } else if (counts) {
214	                        dated.computeIfAbsent(key, (k) -> new TreeMap<>()).put(rs.getDate("from_date").toLocalDate(), value);
215	                    }
216	                }, sheetId);
217	        return new Settings(sheetId, day, dated, policyKept[0] ? policy[0] : now.policyDate(),
218	                now.periodNumberingFrom(), now.perms(), now.graceDays(), now.entryDate(), potKept[0] ? pot[0] : now.pot(), now.fiscalStartMonth(),
219	                now.alertThreshold(), now.escalateAfter(), now.reviewSla(), now.proofKinds(), now.defaultGrade(),
220	                now.scoreMid(), now.scoreHigh(), now.scoreLog());
221	    }
222	
223	    private static final String POLICY_DATE = "policy-date";
224	
225	    private static final String POT = "pot";
226	
227	    /** Records the roles ('' for the standing rule) that may take an action. */
228	    public void recordPerm(String sheetId, String action, String roles) {
229	        jdbc.update("MERGE INTO setting_perm (sheet_id, action, roles) KEY (sheet_id, action) VALUES (?, ?, ?)",
230	                sheetId, action, roles);
231	    }
232	
233	    /** Saves the undated settings. */
234	    public void saveUndated(Settings settings) {
235	        jdbc.update("UPDATE sheet SET policy_date = ?, period_numbering_from = ?, grace_days = ?, entry_date = ?, pot = ?, fiscal_start_month = ?, alert_threshold = ?, escalate_after = ?, review_sla = ?, proof_kinds = ?, default_grade = ?, score_mid = ?, score_high = ?, score_log = ? WHERE id = ?",
236	                settings.policyDate() == null ? null : java.sql.Date.valueOf(settings.policyDate()),
237	                settings.periodNumberingFrom() == null ? null : java.sql.Date.valueOf(settings.periodNumberingFrom()),
238	                settings.graceDays(),
239	                settings.entryDate() == null ? null : java.sql.Date.valueOf(settings.entryDate()),
240	                settings.pot(), settings.fiscalStartMonth(), settings.alertThreshold(), settings.escalateAfter(), settings.reviewSla(), settings.proofKinds(), settings.defaultGrade(),
241	                settings.scoreMid(), settings.scoreHigh(), settings.scoreLog(), settings.sheetId());
242	        history(settings.sheetId(), POLICY_DATE, null,
243	                settings.policyDate() == null ? "" : settings.policyDate().toString());
244	        history(settings.sheetId(), POT, null, settings.pot() == null ? "" : settings.pot().toPlainString());
245	    }
246	}
